window.kbPageData["views/entry/k-82e86c5a22e9f730"] = {"key":"entry/k-82e86c5a22e9f730","state":{"route":"entry/k-82e86c5a22e9f730"},"node":{"id":"k-82e86c5a22e9f730","mode":"k","title":"公务员从事营利活动与兼职限制","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["公务员营利活动和营利性组织兼职禁令"],"qs":["江苏 2024 A类 行测#7"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"《公务员法》第五十九条第十六项禁止公务员违反有关规定从事或者参与营利性活动，并将公务员在企业或者其他营利性组织中兼任职务列入禁止行为。","review":{"definition":"《公务员法》第五十九条第十六项禁止公务员违反有关规定从事或者参与营利性活动，并将公务员在企业或者其他营利性组织中兼任职务列入禁止行为。","explanation":"原条文把“违反有关规定”放在“从事或者参与营利性活动”之前，题干省略了这一限定。D项中熊某主动出资设立以营利为目的的有限责任公司，小股东身份不改变其参与设立的性质。A项的工商联属于人民团体和商会组织，B项的个人证券交易须按相关投资规定判断，C项涉及处置依法继承的股权，三者均有别于D项所述行为。","references":[{"source":"web-b861e36828705722","location":"第五十九条第十六项","quote":"违反有关规定从事或者参与营利性活动，在企业或者其他营利性组织中兼任职务"}],"evidence":"税务人员熊某作为小股东出资设立有限责任公司","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 A类 行测#7":{"paper":"江苏 2024 A类 行测","n":7,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",2],"asrc":["0126a1c8aceee632ea2b.pdf",3],"card":"eb776cae7db026319d933503","links":[{"id":"k-82e86c5a22e9f730","role":"直接考查","why":"该规则为判断题列各类行为是否违规提供直接依据。"}]}},"terms":{},"references":{"web-b861e36828705722":{"name":"《中华人民共和国公务员法》（2018年修订）","url":"https://rd.yj.gov.cn/art/2019/7/11/art_1339764_35481351.html"}},"topics":[],"units":{"k-82e86c5a22e9f730":[["江苏 2024 A类 行测#7"]]}};
